import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# Custom CUDA kernel source for depthwise 2D convolution (element-wise per channel)
conv2d_cpp_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Naive implementation: each output element corresponds to one input channel.
__global__ void conv2d_kernel(const float* out, const float* input,
                               int batch_size, int in_channels,
                               int out_channels,
                               int kernel_h, int kernel_w,
                               int stride_h, int stride_w,
                               int padding_h, int padding_w,
                               int dilation_h, int dilation_w) {
    // Compute global index for output element (b, oc, oh, ow)
    // The total number of threads is batch_size * out_channels * out_h * out_w.
    // We'll compute the indices as:
    //   idx = ((b * out_channels + oc) * out_h * out_w + oh * out_w + ow);
    // For simplicity we just let the kernel launch handle it via grid dimensions.
}

torch::Tensor conv2d_cuda(torch::Tensor input, torch::Tensor output) {
    auto size = input.numel();
    auto out_tensor = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    // Compute strides and padding offsets
    // For the given parameters we assume stride_h=stride_w=1, padding_h=padding_w=0,
    // dilation_h=dilation_w=1.
    conv2d_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), out_tensor.data_ptr<float>(), 
                                              input.shape[0], in_channels, out_channels,
                                              kernel_h, kernel_w, stride_h, stride_w,
                                              padding_h, padding_w, dilation_h, dilation_w);

    return output;
}
"""

# Function signature for load_inline
conv2d_cpp_source_func = "torch::Tensor conv2d_cuda(torch::Tensor input, torch::Tensor output);"

conv2d = load_inline(
    name="conv2d",
    cpp_sources=conv2d_cpp_source_func,
    cuda_sources=conv2d_cpp_source,
    functions=["conv2d_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size_h: int, kernel_size_w: int, stride_h: int = 1, stride_w: int = 1, padding_h: int = 0, padding_w: int = 0, dilation_h: int = 1, dilation_w: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.conv2d_cuda = conv2d   # assign the custom CUDA function

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.conv2d_cuda(x)
